const root=document.documentElement,boot=document.querySelector('.boot'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;addEventListener('load',()=>setTimeout(()=>boot?.classList.add('done'),reduced?0:850));document.getElementById('year').textContent=new Date().getFullYear();const clock=document.getElementById('clock');setInterval(()=>clock.textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date()),1000);const saved=localStorage.getItem('kj-theme');if(saved)root.dataset.theme=saved;document.querySelector('.theme-toggle').onclick=()=>{root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';localStorage.setItem('kj-theme',root.dataset.theme)};const bar=document.querySelector('.progress i'),progress=()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.style.transform=`scaleX(${m?scrollY/m:0})`};addEventListener('scroll',progress,{passive:true});progress();const dialog=document.querySelector('.command'),trigger=document.querySelector('.command-trigger'),input=dialog.querySelector('input'),links=[...dialog.querySelectorAll('.command-list a')],open=()=>{dialog.showModal();setTimeout(()=>input.focus(),20)};trigger.onclick=open;addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();dialog.open?dialog.close():open()}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();open()}});input.oninput=()=>{const q=input.value.toLowerCase();links.forEach(a=>a.hidden=!a.dataset.search.includes(q))};links.forEach(a=>a.onclick=()=>dialog.close());if(!reduced&&matchMedia('(pointer:fine)').matches)document.querySelectorAll('[data-tilt]').forEach(card=>{card.onpointermove=e=>{const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(1200px) rotateX(${y*-2}deg) rotateY(${x*2}deg)`};card.onpointerleave=()=>card.style.transform=''});
